const paths={
  about:'M20 21v-2a7 7 0 0 0-14 0v2M13 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',
  projects:'M3 7V5h6l2 2h10v13H3V7Zm0 3h18',
  experience:'M8 7V4h8v3M3 7h18v14H3V7Zm0 6h18M10 11h4v4h-4z',
  skills:'m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8L12 3Zm7 13 .8 2.2L22 19l-2.2.8L19 22l-.8-2.2L16 19l2.2-.8L19 16',
  contacts:'M3 5h18v14H3V5Zm0 1 9 7 9-7',
  conditions:'M5 3h14v18H5V3Zm4 5h6m-6 4h6m-6 4h4',
  print:'M7 8V3h10v5M7 17H3V8h18v9h-4M7 14h10v7H7v-7Z',
  copy:'M9 8H4v13h12v-5M9 3h12v13H9V3Z',search:'m16 16 5 5M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16'
};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.projects}"/></svg>`;
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sections=[['about','Обо мне'],['projects','Проекты'],['experience','Опыт работы'],['skills','Навыки и AI'],['contacts','Контакты'],['conditions','Сотрудничество']];
const content=document.querySelector('#content'),finder=document.querySelector('#finder'),caseLayer=document.querySelector('#case-layer'),imageLayer=document.querySelector('#image-layer');
let current='about',category='Все',query='',historyStack=['about'],historyIndex=0,lastFocus=null,currentProject=null,toastTimer;
document.querySelector('#main-nav').innerHTML=sections.map(([key,label])=>`<button data-view="${key}">${icon(key)}<span>${label}</span></button>`).join('');
document.querySelector('.dock').innerHTML=sections.slice(0,5).map(([key,label])=>`<button data-view="${key}" aria-label="${label}">${icon(key)}<span class="dock-label">${label}</span></button>`).join('')+`<span class="dock-divider"></span><button data-print aria-label="Версия резюме для печати">${icon('print')}<span class="dock-label">Резюме для печати</span></button>`;
function link(url,label,cls=''){return `<a class="${cls}" href="${url}" target="_blank" rel="noopener">${label}</a>`}
const tags=items=>`<div class="tags">${items.map(x=>`<span>${x}</span>`).join('')}</div>`;
function about(){return `<div class="about-hero"><div><div class="eyebrow"><span class="status-dot"></span>Привет, я</div><h1>Вероника<br><span>Резникова.</span></h1><p class="intro">Веб-дизайнер и арт-директор.<br>Создаю сайты и интерфейсы с вниманием к опыту и эстетике.</p><div class="action-row"><button class="primary" data-view="projects">Смотреть проекты <span>↗</span></button><button class="text-button" data-view="contacts">Давайте познакомимся</button></div></div><div class="portrait-wrap"><img src="assets/portrait.jpg" alt="Вероника Резникова" width="170" height="180"><small>designer, human, me.</small></div></div><div class="stat-strip">${CV.stats.map(s=>`<div><strong>${s.value}</strong><span>${s.label}</span></div>`).join('')}</div><div class="about-bottom"><section class="about-note"><div class="section-heading"><h2>От идеи до запуска</h2></div><p>Создаю сайты, сервисы, приложения и презентации. Веду проекты, помогаю командам и делюсь опытом с дизайнерами. Использую AI для поиска идей и развития концепций.</p><div class="tool-row"><span>Figma</span><span>Adobe</span><span>Tilda</span><span>AI tools</span></div></section><section><div class="section-heading"><h2>Избранный проект</h2><button data-view="projects">Все проекты ↗</button></div><button class="mini-work" data-project="view"><img src="assets/view0.jpg" alt="Превью проекта VIEW" width="150" height="100"><div><h3>VIEW — Digital agency</h3><p>Характер бренда.<br>На языке digital.</p><span class="mini-link">Открыть кейс ↗</span></div></button></section></div>`}
function card(p){return `<button class="project-card" data-project="${p.id}" data-id="${p.id}"><div class="project-visual" style="--project-bg:${p.bg}">${p.cover?`<img src="${p.cover}" alt="${p.title} — превью проекта" loading="lazy">`:`<span class="project-wordmark">${p.wordmark}</span>`}<span class="project-open" aria-hidden="true">↗</span></div><div class="project-meta"><h3>${p.title}</h3><small>${p.category}</small></div><p>${p.type}</p></button>`}
function filteredProjects(){return CV.projects.filter(p=>(category==='Все'||p.category===category)&&`${p.title} ${p.subtitle} ${p.type} ${p.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()))}
function projectGrid(){const list=filteredProjects();return list.length?list.map(card).join(''):`<div class="empty-results"><h3>Ничего не нашлось</h3><p>Попробуйте другое название или выберите все проекты.</p><button class="secondary" id="reset-search">Показать все проекты</button></div>`}
function projects(){return `<div class="page-heading"><div><h1>Проекты</h1><p>Сайты, интерфейсы и немного характера.</p></div>${link('https://www.behance.net/vrreznikova','Behance ↗','secondary')}</div><div class="project-toolbar"><div class="filters" aria-label="Категория проектов">${['Все','Сайты','Интерфейсы','Материалы'].map(x=>`<button data-filter="${x}" class="${category===x?'active':''}" aria-pressed="${category===x}">${x}</button>`).join('')}</div><label class="search">${icon('search')}<input id="project-search" type="search" placeholder="Найти проект" aria-label="Найти проект" value="${escapeHtml(query)}"></label></div><div class="projects-grid" id="projects-grid">${projectGrid()}</div><section class="other-work"><div class="section-heading"><h2>Ещё реализованные сайты</h2></div>${CV.otherProjects.map(p=>link(p.url,`<div><b>${p.title}</b><p>${p.description}</p></div><span>↗</span>`,'link-row')).join('')}<div class="language-note">Больше работ и визуальных экспериментов — ${link('https://www.figma.com/design/hXr6Gv2ZBB8lVtRYuH5d3t/','в Figma ↗')}.</div></section>`}
function experience(){return `<div class="page-heading"><div><h1>Опыт работы</h1><p>Дизайн, управление проектами и обучение.</p></div><a class="secondary" href="cv.html" target="_blank" rel="noopener">Резюме для печати ↗</a></div><div class="timeline">${CV.experience.map(e=>`<article class="experience-item"><div class="experience-top"><h2>${e.link?link(e.link,e.company+' ↗'):e.company}</h2><time>${e.dates}</time></div><div class="role">${e.role}</div><p>${e.description}</p>${tags(e.tags)}</article>`).join('')}</div><section class="education"><h2>Образование</h2><div><div><strong>Белорусский государственный университет</strong><p>Факультет социальных коммуникаций · Бакалавриат</p></div><time>2017 — 2023</time></div><div><div><strong>Adukar</strong><p>Веб-дизайн и UI/UX-дизайн · Курс</p></div><time>2020 — 2021</time></div></section>`}
function skills(){return `<div class="page-heading"><div><h1>Навыки и инструменты</h1><p>Системный подход. Внимание к деталям.</p></div></div><p class="skills-intro">Соединяю исследование, логику и визуальный язык. Умею не только создавать макеты, но и выстраивать процесс вокруг них.</p><div class="skill-group"><h2>Исследую и проектирую</h2><p>Анализ аудитории, рынка и конкурентов, карты эмпатии, User Flow и CJM. Информационная архитектура, wireframes и интерактивные прототипы.</p></div><div class="skill-group"><h2>Создаю дизайн</h2><p>Сайты, сервисы, мобильные приложения и презентации. Адаптивные интерфейсы, UI-компоненты и дизайн-системы. Типографика, композиция и визуальная иерархия.</p></div><div class="skill-group"><h2>Довожу до результата</h2><p>Дизайн-аудит, редизайн, подготовка макетов к разработке и контроль реализации. Взаимодействие с разработчиками и маркетологами, презентация и аргументация решений.</p></div><div class="skill-group"><h2>Веду команду</h2><p>Арт-дирекшн, коммуникация с клиентами, сметы и документация. Координация дизайнеров и кураторов, наставничество и развивающая обратная связь.</p></div><div class="skill-group"><h2>Рабочие инструменты</h2><div class="skills-tools"><span>Figma</span><span>Photoshop</span><span>Illustrator</span><span>Tilda</span></div></div><section class="ai-note"><h2>AI — часть моего процесса</h2><p>Активно использую AI-инструменты для генерации идей, концепций и визуальных референсов, а также для ускорения дизайн-процессов.</p><div class="ai-steps"><div><b>01 / Идеи</b>Исследую разные направления и формулирую гипотезы.</div><div><b>02 / Концепции</b>Развиваю визуальные подходы и собираю референсы.</div><div><b>03 / Процесс</b>Ускоряю рабочие этапы, сохраняя авторский контроль.</div></div></section><p class="language-note">Русский — родной · Английский — B1</p>`}
function contacts(){return `<section class="contact-hero"><div class="eyebrow"><span class="status-dot"></span>Проектно или в команду</div><h1>Начнём с хорошего<br><span style="color:#68806b">разговора.</span></h1><p>Открыта к интересным задачам и долгосрочному сотрудничеству. Расскажите о вашем проекте — обсудим, чем я могу быть полезна.</p>${link(CV.telegram,'Написать в Telegram ↗','primary')}</section><div class="contact-lines"><div class="contact-line"><div><small>Telegram · Предпочтительно</small>${link(CV.telegram,'@Veronika_reznikova ↗')}</div><button data-copy="@Veronika_reznikova" aria-label="Скопировать Telegram">${icon('copy')}</button></div><div class="contact-line"><div><small>Электронная почта</small><a href="mailto:${CV.email}">${CV.email}</a></div><button data-copy="${CV.email}" aria-label="Скопировать почту">${icon('copy')}</button></div></div><div class="contact-socials">${link('https://www.instagram.com/webvvv/','Instagram ↗')}${link('https://ru.pinterest.com/webvvv/','Pinterest ↗')}${link('https://www.behance.net/vrreznikova','Behance ↗')}${link('https://dprofile.ru/webvvv','Dprofile ↗')}</div><button class="conditions-link" data-view="conditions">Как я работаю: условия сотрудничества ↗</button><p class="language-note">Беларусь, Минск · Пн–пт, 11:00–19:00 (UTC+3)</p>`}
const conditions=[['Рабочий график','Понедельник — пятница, 11:00–19:00 по московскому времени (UTC+3). Вне рабочего времени отвечаю на срочные вопросы или по предварительной договорённости.'],['Материалы и сроки','Для соблюдения сроков важно вовремя предоставлять тексты, фото, видео и другие материалы. Задержки контента сдвигают сроки проекта.'],['Договор и документы','Работаю по официальному договору РБ. До старта подписываем договор оказания услуг и техническое задание, по завершении — акт выполненных работ. Для заказчиков из других стран — договор-оферта на русском или английском языке, юрисдикция РБ.'],['Поэтапная оплата','Каждый этап начинается после 100% оплаты за него. После завершения текущего этапа переходим к оплате и выполнению следующего.'],['Срочные задачи','Работа в сжатые сроки или вне стандартного графика: от +20% до ×2 к стоимости в зависимости от срочности и объёма.'],['Портфолио и NDA','Готовый проект могу показывать в портфолио, социальных сетях и промоматериалах. Ограничения публичности обсуждаем заранее. NDA или запрет на публикацию — +15% к стоимости проекта.']];
function cooperation(){return `<div class="page-heading"><div><h1>Сотрудничество</h1><p>Прозрачный процесс — спокойная работа.</p></div></div><div class="conditions-list">${conditions.map(([title,text],i)=>`<details ${i===0?'open':''}><summary>${title}</summary><p>${text}</p></details>`).join('')}</div><div class="action-row" style="margin-top:25px">${link(CV.telegram,'Обсудить проект ↗','primary')}</div>`}
const views={about,projects,experience,skills,contacts,conditions:cooperation};
function setActive(){document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===current;b.classList.toggle('active',active);if(b.closest('#main-nav'))active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current')});document.querySelector('#go-back').disabled=historyIndex===0;document.querySelector('#go-forward').disabled=historyIndex===historyStack.length-1}
function renderView(view,{push=true,focus=false,updateHash=true}={}){if(!views[view])view='about';if(currentProject)closeCase(false);finder.hidden=false;document.querySelector('#minimized-message').hidden=true;current=view;content.innerHTML=views[view]();content.scrollTop=0;const label=sections.find(x=>x[0]===view)[1];document.querySelector('#window-title').textContent=label;document.querySelector('#status-path').textContent=`Рабочий стол / ${label}`;document.title=`${label} — Вероника Резникова`;if(push&&historyStack[historyIndex]!==view){historyStack=historyStack.slice(0,historyIndex+1);historyStack.push(view);historyIndex++}setActive();closeMenu();if(updateHash)history.replaceState(null,'',`#${view}`);if(focus)content.focus({preventScroll:true});bindSearch()}
function bindSearch(){const search=document.querySelector('#project-search');if(search)search.addEventListener('input',e=>{query=e.target.value;document.querySelector('#projects-grid').innerHTML=projectGrid()})}
function closeMenu(){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');document.querySelector('#menu-toggle').setAttribute('aria-label','Открыть разделы')}
function showToast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,2300)}
function caseMarkup(p,index){return `<section class="case-window" role="dialog" aria-modal="true" aria-labelledby="case-heading" tabindex="-1"><div class="case-bar"><div class="traffic"><button class="red" data-close-case aria-label="Закрыть проект"></button></div><strong>Проекты / ${p.title}</strong><div class="case-controls"><button data-prev-project aria-label="Предыдущий проект" ${index===0?'disabled':''}>‹</button><button data-next-project aria-label="Следующий проект" ${index===CV.projects.length-1?'disabled':''}>›</button></div></div><div class="case-body"><div class="case-head"><div><div class="case-type">${p.type}</div><h2 id="case-heading">${p.title}</h2></div>${link(p.url,p.linkLabel+' ↗','primary')}</div><div class="case-cover" style="--project-bg:${p.bg}">${p.cover?`<img src="${p.cover}" alt="${p.title} — обложка проекта">`:`<span class="project-wordmark">${p.wordmark}</span>`}</div>${tags(p.tags)}<p class="case-intro">${p.intro}</p><div class="case-role"><span>Моя роль</span><strong>${p.role}</strong></div><div class="case-copy"><h3>Задача</h3><p>${p.task}</p></div><div class="case-copy"><h3>Что сделано</h3><p>${p.solution}</p></div>${p.credit?`<p class="case-credit">${p.credit}</p>`:''}${p.images?`<div class="gallery">${p.images.map((src,i)=>`<button data-image="${src}" aria-label="Увеличить изображение ${i+1} проекта ${p.title}"><img src="${src}" alt="${p.title} — экран ${i+1}" loading="lazy"></button>`).join('')}</div>`:''}${p.extraLinks?`<div class="case-extra-links">${p.extraLinks.map(([text,url])=>link(url,text+' ↗')).join('')}</div>`:''}<div class="case-bottom"><button class="text-button" data-close-case>← Назад к резюме</button>${index<CV.projects.length-1?`<button class="secondary" data-next-project>Следующий проект →</button>`:''}</div></div></section>`}
function openCase(id){const p=CV.projects.find(p=>p.id===id);if(!p)return;if(!currentProject)lastFocus=document.activeElement;currentProject=id;caseLayer.innerHTML=caseMarkup(p,CV.projects.indexOf(p));caseLayer.hidden=false;document.querySelector('main').inert=true;document.querySelector('.menubar').inert=true;history.replaceState(null,'',`#projects/${id}`);document.title=`${p.title} — Вероника Резникова`;caseLayer.querySelector('[role=dialog]').focus({preventScroll:true})}
function closeCase(updateHash=true){currentProject=null;imageLayer.hidden=true;caseLayer.hidden=true;caseLayer.innerHTML='';document.querySelector('main').inert=false;document.querySelector('.menubar').inert=false;if(updateHash)history.replaceState(null,'',`#${current}`);document.title=`${sections.find(s=>s[0]===current)[1]} — Вероника Резникова`;if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true})}
function stepProject(delta){const index=CV.projects.findIndex(p=>p.id===currentProject);const next=CV.projects[index+delta];if(next)openCase(next.id)}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b){if(e.target===caseLayer)closeCase();if(e.target===imageLayer){imageLayer.hidden=true;caseLayer.querySelector('[role=dialog]').inert=false;caseLayer.querySelector('[role=dialog]').focus()}return}if(b.dataset.view){e.preventDefault();renderView(b.dataset.view,{focus:true})}if(b.dataset.project)openCase(b.dataset.project);if(b.hasAttribute('data-print'))window.open('cv.html','_blank','noopener');if(b.dataset.filter){category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el.dataset.filter===category);el.setAttribute('aria-pressed',el.dataset.filter===category)});document.querySelector('#projects-grid').innerHTML=projectGrid()}if(b.id==='reset-search'){category='Все';query='';renderView('projects',{push:false,focus:true})}if(b.hasAttribute('data-close-case'))closeCase();if(b.hasAttribute('data-prev-project'))stepProject(-1);if(b.hasAttribute('data-next-project'))stepProject(1);if(b.dataset.image){imageLayer.innerHTML=`<div role="dialog" aria-modal="true" aria-label="Просмотр изображения"><button data-close-image aria-label="Закрыть изображение">×</button><img src="${b.dataset.image}" alt="Увеличенное изображение проекта ${currentProject}"></div>`;imageLayer.hidden=false;caseLayer.querySelector('[role=dialog]').inert=true;imageLayer.querySelector('button').focus()}if(b.hasAttribute('data-close-image')){imageLayer.hidden=true;caseLayer.querySelector('[role=dialog]').inert=false;caseLayer.querySelector('[role=dialog]').focus()}if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);showToast('Скопировано')}catch{showToast('Скопируйте адрес из строки контакта')}}});
document.querySelector('#menu-toggle').addEventListener('click',()=>{const open=document.querySelector('#sidebar').classList.toggle('open');const b=document.querySelector('#menu-toggle');b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Закрыть разделы':'Открыть разделы')});
for(const id of ['close-window','minimize-window'])document.querySelector('#'+id).addEventListener('click',()=>{finder.hidden=true;document.querySelector('#minimized-message').hidden=false;document.querySelector('.dock button').focus()});
document.querySelector('#maximize-window').addEventListener('click',()=>{finder.classList.toggle('maximized');finder.style.left='';finder.style.top='';finder.style.transform='';document.querySelector('#maximize-window').setAttribute('aria-label',finder.classList.contains('maximized')?'Вернуть размер окна':'Развернуть окно')});
document.querySelector('#go-back').addEventListener('click',()=>{if(historyIndex>0){historyIndex--;renderView(historyStack[historyIndex],{push:false,focus:true})}});document.querySelector('#go-forward').addEventListener('click',()=>{if(historyIndex<historyStack.length-1){historyIndex++;renderView(historyStack[historyIndex],{push:false,focus:true})}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!imageLayer.hidden){imageLayer.hidden=true;caseLayer.querySelector('[role=dialog]').inert=false;caseLayer.querySelector('[role=dialog]').focus()}else if(currentProject)closeCase();else closeMenu()}if(e.key==='Tab'&&currentProject){const scope=!imageLayer.hidden?imageLayer:caseLayer;const elements=[...scope.querySelectorAll('button:not(:disabled),a[href],[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===scope.querySelector('[role=dialog]'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{const [section,id]=location.hash.slice(1).split('/');renderView(section||'about',{push:true,updateHash:false});if(id)openCase(id)});
// Drag only the title bar; clamp the window so controls remain reachable.
let drag=null;const bar=document.querySelector('#windowbar');bar.addEventListener('pointerdown',e=>{if(e.target.closest('button')||innerWidth<=640||finder.classList.contains('maximized'))return;const r=finder.getBoundingClientRect();drag={dx:e.clientX-r.left,dy:e.clientY-r.top};bar.setPointerCapture(e.pointerId)});bar.addEventListener('pointermove',e=>{if(!drag)return;const desktopTop=document.querySelector('.desktop').getBoundingClientRect().top;const x=Math.max(8,Math.min(innerWidth-finder.offsetWidth-8,e.clientX-drag.dx));const y=Math.max(8,Math.min(innerHeight-desktopTop-110,e.clientY-drag.dy-desktopTop));finder.style.transform='none';finder.style.left=x+'px';finder.style.top=y+'px'});bar.addEventListener('pointerup',()=>drag=null);bar.addEventListener('pointercancel',()=>drag=null);window.addEventListener('resize',()=>{finder.style.left='';finder.style.top='';finder.style.transform=''});
function clock(){const now=new Date();document.querySelector('#clock').textContent=new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Minsk',weekday:'short',hour:'2-digit',minute:'2-digit'}).format(now);document.querySelector('#clock').dateTime=now.toISOString()}clock();setInterval(clock,60000);
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();content.focus()});
const [start,id]=location.hash.slice(1).split('/');historyStack=[views[start]?start:'about'];renderView(start||'about',{push:false});if(id)openCase(id);
